const alert = $input.first().json;
const allowedRules = ['100160', '100161', '100162', '100170', '100171', '100175'];
const ruleId = String(alert.rule?.id || alert.id || '');

if (!allowedRules.includes(ruleId)) {
  return [];
}

const agentName = alert.agent?.name || 'unknown';
const ruleLevel = Number(alert.rule?.level || 0);
const ruleDesc = alert.rule?.description || 'Suricata alert';
const data = alert.data || {};
const srcIp = data.src_ip || 'N/A';
const dstIp = data.dest_ip || 'N/A';
const dstPort = data.dest_port || 'N/A';
const sig = data.alert?.signature || ruleDesc;
const action = data.alert?.action || 'alert';

return [{
  json: {
    alert,
    ruleId,
    ruleLevel,
    agentName,
    srcIp,
    dstIp,
    dstPort,
    sig,
    action,
    isCritical: ruleLevel >= 13 || ['100160', '100161', '100162', '100170', '100175'].includes(ruleId)
  }
}];

const item = $input.first().json;
const key = `${item.srcIp}_${item.ruleId}`;
const now = Date.now();

const staticData = $getWorkflowStaticData('global');
staticData.dedupe = staticData.dedupe || {};

const lastSeen = staticData.dedupe[key];
// Dedupe for 24 hours (86400000 ms)
if (lastSeen && (now - lastSeen < 86400000)) {
  return [];
}

staticData.dedupe[key] = now;
return [{ json: item }];

const item = $input.first().json;
const botToken = $env.SOC_TELEGRAM_BOT_TOKEN || '{{SOC_TG_TOKEN}}';
const chatId = '-1004301734497';

const text = `🔴 <b>[SURICATA IPS ALERT]</b>\n` +
  `<b>Type:</b> ${item.ruleId === '100170' ? 'PACKET DROP (NFQUEUE)' : 'HOST AUTO-BLOCK (AR)'}\n` +
  `<b>Rule ID:</b> ${item.ruleId} (Level ${item.ruleLevel})\n` +
  `<b>Agent:</b> ${item.agentName}\n` +
  `<b>Attacker:</b> <code>${item.srcIp}</code>\n` +
  `<b>Target:</b> <code>${item.dstIp}:${item.dstPort}</code>\n` +
  `<b>Signature:</b> ${item.sig}`;

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${botToken}/sendMessage`,
    body: {
      chat_id: chatId,
      text: text,
      parse_mode: 'HTML',
      disable_web_page_preview: true
    },
    json: true
  });
} catch (err) {
  // ignore TG delivery failure so flow does not crash
}

return [{ json: item }];
